    font-size: 0.72rem;
    color: #707a91;
    margin-bottom: 8px;
    line-height: 1.5;
}

.od-alert-meta span {
    color: #94a3b8;
}

.od-btn-clear {
    background: transparent;
    border: 1px solid #2d364f;
    color: #707a91;
    border-radius: 6px;
    padding: 5px 10px;
    font-size: 0.7rem;
    font-weight: 600;
    cursor: pointer;
    transition: color 0.2s, border-color 0.2s;
    width: 100%;
}

.od-btn-clear:hover {
    color: #10b981;
    border-color: #10b981;
}

/* =========================================
   STAT STRIP BELOW STREAM
   ========================================= */
.od-stream-bottom {
    grid-column: 1 / 2;
    grid-row: 2 / 3;
    background: #1e2539;
    border-radius: 16px;
    border: 1px solid #2d364f;
    padding: 14px 20px;
    display: flex;
    align-items: center;
    gap: 24px;
}

.od-stat {
    display: flex;
    align-items: center;
    gap: 10px;
}

.od-stat-icon {
    width: 36px;
    height: 36px;
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1rem;
}

.od-stat-icon.cyan { background: rgba(6, 182, 212, 0.12); color: #22d3ee; }
.od-stat-icon.orange { background: rgba(245, 158, 11, 0.12); color: #fbbf24; }
.od-stat-icon.red { background: rgba(239, 68, 68, 0.12); color: #f87171; }

.od-stat-info h3 {
    margin: 0;
    font-size: 1.2rem;
    color: #f8fafc;
    line-height: 1;
}

.od-stat-info p {
    margin: 2px 0 0;
    font-size: 0.7rem;
    color: #707a91;
}

/* =========================================
   ANIMATIONS
   ========================================= */
@keyframes odPulse {
    0%, 100% { opacity: 0.6; }
    50% { opacity: 1; }
}

/* =========================================
   RESPONSIVE
   ========================================= */
@media (max-width: 1024px) {
    .od-grid {
        grid-template-columns: 1fr;
        grid-template-rows: auto;
    }

    .od-right-column {
        grid-column: 1 / 2;
        grid-row: auto;
    }

    .od-stream-bottom {
        grid-column: 1 / 2;
        grid-row: auto;
        flex-wrap: wrap;
        gap: 16px;
    }
}

